function lruOps(capacity, ops) {
  const head = {}, tail = {}, where = new Map(), out = []; head.next = tail; tail.prev = head //@init
  const unlink = node => { node.prev.next = node.next; node.next.prev = node.prev }
  const toFront = node => { node.next = head.next; node.prev = head; head.next.prev = node; head.next = node }
  for (const [kind, key, value] of ops) {
    if (kind === 'get') {
      const node = where.get(key)
      if (!node) { out.push(-1); continue } //@miss
      unlink(node); toFront(node); out.push(node.val) //@hit
      continue
    }
    if (where.has(key)) unlink(where.get(key))
    const node = { key, val: value }; where.set(key, node); toFront(node) //@put
    if (where.size > capacity) {
      const old = tail.prev; unlink(old); where.delete(old.key) //@evict
    }
  }
  return out //@done
}

