class Node:
    def __init__(self, key=0, val=0):
        self.key, self.val, self.prev, self.next = key, val, None, None

def lru_ops(capacity, ops):
    head, tail, where, out = Node(), Node(), {}, []; head.next, tail.prev = tail, head  #@init
    def unlink(node): node.prev.next, node.next.prev = node.next, node.prev
    def to_front(node): node.next, node.prev = head.next, head; head.next.prev = node; head.next = node
    for op in ops:
        key = op[1]
        if op[0] == "get":
            node = where.get(key)
            if node is None: out.append(-1); continue  #@miss
            unlink(node); to_front(node); out.append(node.val)  #@hit
            continue
        if key in where: unlink(where[key])
        node = Node(key, op[2]); where[key] = node; to_front(node)  #@put
        if len(where) > capacity:
            old = tail.prev; unlink(old); del where[old.key]  #@evict
    return out  #@done

