class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.where = {}  # key -> node
        self.head, self.tail = {}, {}  # sentinels: no edge cases
        self.head["next"], self.tail["prev"] = self.tail, self.head

    def _unlink(self, node):
        node["prev"]["next"], node["next"]["prev"] = node["next"], node["prev"]

    def _to_front(self, node):
        node["next"], node["prev"] = self.head["next"], self.head
        self.head["next"]["prev"] = node
        self.head["next"] = node

    def get(self, key):
        node = self.where.get(key)
        if node is None:
            return -1
        self._unlink(node)
        self._to_front(node)  # most recent
        return node["val"]

    def put(self, key, val):
        if key in self.where:
            self._unlink(self.where[key])
        node = {"key": key, "val": val}
        self.where[key] = node
        self._to_front(node)
        if len(self.where) > self.capacity:
            old = self.tail["prev"]  # least recent
            self._unlink(old)
            del self.where[old["key"]]

