class LRUCache {
  constructor(capacity) {
    this.capacity = capacity
    this.where = new Map() // key -> node
    this.head = {} // sentinels: no edge cases
    this.tail = { prev: this.head }
    this.head.next = this.tail
  }

  unlink(node) {
    node.prev.next = node.next
    node.next.prev = node.prev
  }

  toFront(node) {
    node.next = this.head.next
    node.prev = this.head
    this.head.next.prev = node
    this.head.next = node
  }

  get(key) {
    const node = this.where.get(key)
    if (!node) return -1
    this.unlink(node)
    this.toFront(node) // most recent
    return node.val
  }

  put(key, val) {
    if (this.where.has(key)) this.unlink(this.where.get(key))
    const node = { key, val }
    this.where.set(key, node)
    this.toFront(node)
    if (this.where.size > this.capacity) {
      const old = this.tail.prev // least recent
      this.unlink(old)
      this.where.delete(old.key)
    }
  }
}

