type CacheNode = { key: number; val: number; prev?: CacheNode; next?: CacheNode }

class LRUCache {
  capacity: number
  where = new Map<number, CacheNode>() // key -> node
  head: CacheNode = { key: -1, val: -1 } // sentinels: no edge cases
  tail: CacheNode = { key: -1, val: -1 }

  constructor(capacity: number) {
    this.capacity = capacity
    this.head.next = this.tail
    this.tail.prev = this.head
  }

  unlink(node: CacheNode): void {
    node.prev!.next = node.next
    node.next!.prev = node.prev
  }

  toFront(node: CacheNode): void {
    node.next = this.head.next
    node.prev = this.head
    this.head.next!.prev = node
    this.head.next = node
  }

  get(key: number): number {
    const node = this.where.get(key)
    if (!node) return -1
    this.unlink(node)
    this.toFront(node) // most recent
    return node.val
  }

  put(key: number, val: number): void {
    const existing = this.where.get(key)
    if (existing) this.unlink(existing)
    const node: CacheNode = { key, val }
    this.where.set(key, node)
    this.toFront(node)
    if (this.where.size > this.capacity) {
      const old = this.tail.prev! // least recent
      this.unlink(old)
      this.where.delete(old.key)
    }
  }
}

