from collections import deque

def rate_limit(limit, window, times):
    log = deque()
    out = []
    for t in times:
        while log and log[0] <= t - window:
            log.popleft()
        if len(log) < limit:
            log.append(t)
            out.append(True)
        else:
            out.append(False)
    return out

